	public class IndiaEInvoiceAuthorisationRecordCreatorTest : TestCaseWithFactory
	{
		public void TestConstructor()
		{
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be null.\r\nParameter name: response", () => new IndiaEInvoiceAuthorisationRecordCreator(null, ZGuid.NewZGuid()));
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be null.\r\nParameter name: response.AckNo", () => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponseWith(r => r.AckNo = null), ZGuid.NewZGuid()));
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be null.\r\nParameter name: response.AckDateTime", () => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponseWith(r => r.AckDateTime = null), ZGuid.NewZGuid()));
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be null.\r\nParameter name: response.Irn", () => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponseWith(r => r.Irn = null), ZGuid.NewZGuid()));
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be null.\r\nParameter name: response.SignedInvoiceAsJwt", () => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponseWith(r => r.SignedInvoiceAsJwt = null), ZGuid.NewZGuid()));
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be null.\r\nParameter name: response.SignedQRCodeAsJwt", () => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponseWith(r => r.SignedQRCodeAsJwt = null), ZGuid.NewZGuid()));

			AssertNoExceptionThrown("IndiaEInvoiceResponse.Status is unused and should not trigger an ArgumentException", () => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponseWith(r => r.Status = null), ZGuid.NewZGuid()));
			AssertNoExceptionThrown(() => new IndiaEInvoiceAuthorisationRecordCreator(CreateResponse(), ZGuid.NewZGuid()));
		}

		public void TestCreate()
		{
			var arInvoice = (ARInvoice)ObjectCreator.CreateInvoiceWithLine(typeof(ARInvoice), "001", ObjectCreator.AUD, 1.0m, 100.00m, 10.00m, 100.00m, 10.00m, ObjectCreator.Debtor, ObjectCreator.CC1.PK);
			arInvoice.AH_TransactionReference = "REF001";
			Factory.Save();

			var response = CreateResponse();
			var createdRecord = new IndiaEInvoiceAuthorisationRecordCreator(response, arInvoice.PK).Create(Factory);
			Factory.Save();

			var record = Factory.Load<IndiaAccTransactionHeaderAuthorisationRecord>(createdRecord.PK);
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_RecordType), AccTransactionHeaderAuthorisationRecordTypes.India, record.AHF_RecordType);
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_ParentId), createdRecord.AHF_ParentId, record.AHF_ParentId);
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_ParentTableCode), "AH", record.AHF_ParentTableCode);
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_Counter), "17100000054", record.AHF_Counter);
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_Number), "d056a57cc7cfcc6c9230aa0014e439259d0dc57cfa4eea2326253011fd53ea7e", record.AHF_Number);
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_DateTime), new ZDateTimeOffset(2019, 12, 25, 12, 3, 0, TimeSpan.FromHours(5.5)), record.AHF_DateTime);     // Offset is based on IST timezone
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_VerificationUrl), "eyJhbGciOiJodHRwOi8vd3d3LnczLm9yZy8yMDAxLzA0L3htbGRzaWctbW9yZSNyc2Etc2hhMjU2Iiwia2lkIjoiRTc4MDhFNkZGMDNFMTMyODUzMzBCMDQxQjNFMEEzQUVDNDc4MTMyMCIsInR5cCI6IkpXVCIsIng1dCI6IjU0Q09iX0EtRXloVE1MQkJzLUNqcnNSNEV5QSJ9..UbnWZAI_lq9s9JK8_MovcmjpMPIJnv2-4qGkiXegggQbry_0fJxjwaR8fwCjK_-HVeMujnw8C7F3ITrxKIg5RsdDMzAvLrCNE0K3QkNHGczbvyxhJ02VRFl 1wrQoArxSW1RiyGssLSbH_4tdQ6vke0nSUajXRXvXX2yUeI01CyLsbf2FDNIq46MrDmka5RPNGp0dCx4uX2gkmsCx0Yb0CKjqFI176sTbxOQDHQtRCAfJ0I6dwwggVkfnC3p2F-x6GhEls_7GVsFg1 Z6k4A_aB89c3N6CaWfe8DOQEJTjWaPggMUa2-1hDE1ODTBcIlLcOwB-8jT971hZWgtBubUzFg", record.AHF_VerificationUrl);
			var expectedAuthData = ZBlob.FromAscii("eyJhbGciOiJodHRwOi8vd3d3LnczLm9yZy8yMDAxLzA0L3htbGRzaWctbW9yZSNyc2Etc2hhMjU2Iiwia2lkIjoiRTc4MDhFNkZGMDNFMTMyODUzMzBCMDQxQjNFMEEzQUVDNDc4MTMyMCIsInR5cCI6IkpXVCIsIng1dCI6IjU0Q09iX0EtRXloVE1MQkJzLUNqcnNSNEV5QSJ9..II0jejF0wOrY0CPwIb6oQsSBYilvFSNHZqQJHYOsFt7txrpAvLlCEo4CDNUhPZGWZ6IeERuoY2ScXKNIsCIMQR_9dc0E_fmsaN5XUscxBV3nqPNIkusFcmzjxu59sT8MzcaFqDWfqHunkA-klW40M7oVy6HtL5eI0zbmNoZpdl2yB1Fxfx5AF_vcDv9vWV2u6i39XQ0KdTSbkTAVStdXHix2hE0TlHtHB9Tqt7i9umNPJc_Uf5Kpn4q HiOPvFT2uxhw1N7bIU00cc-PDIqzlLk2VnLb2Zko7wSgYAMrf5G1hn5Op4lbyQe9EwxOPcvJPjJBJsoOmFTbxd1IRgewm7g");
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_AuthorisationData), expectedAuthData, record.AHF_AuthorisationData);
			var expectedPublicKey = new ZBlob(Convert.FromBase64String(""));
			AssertEquals(nameof(IndiaAccTransactionHeaderAuthorisationRecord.AHF_PublicKey), expectedPublicKey, record.AHF_PublicKey);
		}

		public void TestCreate_WithInvalidAckDateTime()
		{
			var response = CreateResponse();
			response.AckDateTime = "not a date";
			AssertExceptionThrown<FormatException>("An invalid AckDateTime field should throw; assumption: the response reader has already validated it.", () => new IndiaEInvoiceAuthorisationRecordCreator(response, ZGuid.NewZGuid()).Create(Factory));
		}

